import json

class Document:
    def __init__(self, id, data):
        self.id = id
        self.data = data

    def to_json(self):
        return json.dumps({"id": self.id, "data": self.data})

from database_client import get_datastore_client

def fetch_document(document_id: str):
    client = get_datastore_client()
    key = client.key('Document', document_id)
    entity = client.get(key)
    if entity:
        return {"status": "success", "document_id": document_id, "data": dict(entity)}
    else:
        return {"status": "not_found", "document_id": document_id}

from database_client import get_datastore_client
from google.cloud import datastore

def conditional_update(document_id: str, field_to_check: str, expected_value: any, updates: dict):
    client = get_datastore_client()
    key = client.key('Document', document_id)

    with client.transaction():
        entity = client.get(key)
        if not entity:
            return {"status": "not_found", "document_id": document_id}

        if entity.get(field_to_check) == expected_value:
            entity.update(updates)
            client.put(entity)
            return {"status": "success", "document_id": document_id}
        else:
            return {"status": "condition_failed", "document_id": document_id}

from google.cloud import translate_v2 as translate

def translate_text(text_content: str, target_language: str):
    translate_client = translate.Client()

    result = translate_client.translate(text_content, target_language=target_language)

    return {"status": "success", "translated_text": result['translatedText'], "detected_source_language": result['detectedSourceLanguage']}
